// Package contract mirrors packages/usage-core: the UsageSnapshot shape, its
// fail-closed validation, and the exact serialization the server's dedup hash
// is computed over. Byte-level drift here breaks ingest dedup and burns D1
// quota, so the goldens in goldens/ are produced by the TypeScript
// implementation and must never be regenerated by hand.
package contract

import (
	_ "embed"
	"encoding/json"
	"strings"
	"testing"
	"time"
)

//go:embed goldens/snapshot-hash.json
var snapshotHashGoldens []byte

// goldenCase is one entry of goldens/snapshot-hash.json, produced by
// packages/usage-core's snapshotHashPayload for the same logical snapshot.
type goldenCase struct {
	Name        string `json:"name"`
	Key         string `json:"key"`
	HashPayload string `json:"hashPayload"`
}

func loadGoldenCases(t *testing.T) []goldenCase {
	t.Helper()
	var cases []goldenCase
	if err := json.Unmarshal(snapshotHashGoldens, &cases); err != nil {
		t.Fatalf("parse goldens: %v", err)
	}
	if len(cases) == 0 {
		t.Fatal("no golden cases")
	}
	return cases
}

// goldenSnapshotByName rebuilds the snapshot each golden was generated from.
// Keep this in lockstep with scripts that regenerate the goldens (see
// goldens/README.md).
func goldenSnapshotByName(t *testing.T, name string) Snapshot {
	t.Helper()
	base := Snapshot{
		Source:       SourceCodex,
		UsageDate:    "2026-05-09",
		Timezone:     "Asia/Shanghai",
		Model:        "gpt-5",
		InputTokens:  10,
		OutputTokens: 2,
		TotalTokens:  17,
		CacheRead:    5,
		CostUSD:      0.01,
		SessionCount: 1,
		CollectedAt:  "2026-05-09T10:00:00.000Z",
	}
	switch name {
	case "base":
		return base
	case "with-correction":
		base.Correction = CorrectionCodexContextPricing
		return base
	case "cost-unavailable-grok":
		base.Source = SourceGrokBuild
		base.CostUSD = 0
		return base
	case "all-zero":
		base.InputTokens, base.OutputTokens, base.CacheCreation = 0, 0, 0
		base.CacheRead, base.TotalTokens = 0, 0
		base.CostUSD, base.SessionCount = 0, 0
		return base
	case "unicode-model":
		base.Model = "módel/中文-模型"
		return base
	case "extreme-tokens":
		base.InputTokens, base.TotalTokens = MaxSnapshotTokens, MaxSnapshotTokens
		return base
	case "tiny-cost-exp":
		base.CostUSD = 1e-7
		return base
	case "tiny-cost-fixed":
		base.CostUSD = 5e-7
		return base
	case "fractional-cost":
		// Runtime arithmetic: Go's constant folder would round 0.1+0.2
		// exactly once (giving exactly 0.3's double), while TS computes it
		// at runtime and lands one ulp higher. The golden bytes come from
		// the runtime result, so this must be runtime arithmetic too.
		a, b := 0.1, 0.2
		base.CostUSD = a + b
		return base
	case "timezone-etc-gmt":
		base.Timezone = "Etc/GMT+5"
		return base
	default:
		t.Fatalf("unknown golden case %q", name)
		return Snapshot{}
	}
}

func TestSnapshotHashPayloadMatchesTypeScriptGoldens(t *testing.T) {
	for _, golden := range loadGoldenCases(t) {
		t.Run(golden.Name, func(t *testing.T) {
			snapshot := goldenSnapshotByName(t, golden.Name)
			if got := snapshot.HashPayload(); got != golden.HashPayload {
				t.Errorf("hash payload drift\ngot:  %s\nwant: %s", got, golden.HashPayload)
			}
			if got := SnapshotKey(snapshot.Source, snapshot.UsageDate, snapshot.Model); got != golden.Key {
				t.Errorf("key drift: got %q want %q", got, golden.Key)
			}
		})
	}
}

// The payload must be byte-identical to TS JSON.stringify for the float cases
// too: encoding/json is not trusted for this (map key order, float formatting
// differs across Go versions), which is why HashPayload assembles by hand.
func TestHashPayloadDoesNotDependOnEncodingJSONFloats(t *testing.T) {
	snapshot := goldenSnapshotByName(t, "fractional-cost")
	// 0.1+0.2 in IEEE double is 0.30000000000000004; TS JSON.stringify emits
	// the shortest round-trip form, which Go's strconv.FormatFloat(-1) matches.
	if !strings.Contains(snapshot.HashPayload(), `"costUsd":0.30000000000000004`) {
		t.Errorf("unexpected float form: %s", snapshot.HashPayload())
	}
}

func TestSnapshotKeyUsesNULSeparator(t *testing.T) {
	if got := SnapshotKey(SourceCodex, "2026-05-09", "gpt-5"); got != "codex\x002026-05-09\x00gpt-5" {
		t.Errorf("key: got %q", got)
	}
}

// Validation must reject what the Zod superRefine rejects, with the same
// shape of rule: cross-field and cost-unavailability, not just field shapes.
func TestValidateFailClosedCases(t *testing.T) {
	cases := []struct {
		name    string
		mutate  func(*Snapshot)
		wantErr string
	}{
		{
			name:    "cacheRead exceeds total",
			mutate:  func(s *Snapshot) { s.CacheRead = 100; s.TotalTokens = 17 },
			wantErr: "cacheReadTokens must not exceed totalTokens",
		},
		{
			name:    "grok cost must be zero",
			mutate:  func(s *Snapshot) { s.Source = SourceGrokBuild; s.CostUSD = 0.5 },
			wantErr: "Grok Build source costs are unavailable; costUsd must be 0",
		},
		{
			name:    "dsh cost must be zero",
			mutate:  func(s *Snapshot) { s.Source = SourceDeepSeekHarness; s.CostUSD = 0.5 },
			wantErr: "DeepSeek Harness source costs are unavailable; costUsd must be 0",
		},
		{
			name:    "antigravity cost must be zero",
			mutate:  func(s *Snapshot) { s.Source = SourceAntigravity; s.CostUSD = 0.5 },
			wantErr: "Antigravity source costs are unavailable; costUsd must be 0",
		},
		{
			name:    "negative tokens",
			mutate:  func(s *Snapshot) { s.InputTokens = -1 },
			wantErr: "inputTokens",
		},
		{
			name:    "token ceiling",
			mutate:  func(s *Snapshot) { s.InputTokens = MaxSnapshotTokens + 1 },
			wantErr: "inputTokens",
		},
		{
			name:    "cost ceiling",
			mutate:  func(s *Snapshot) { s.CostUSD = MaxSnapshotCostUSD + 1 },
			wantErr: "costUsd",
		},
		{
			name:    "empty model",
			mutate:  func(s *Snapshot) { s.Model = "" },
			wantErr: "model",
		},
		{
			// kimi joined the closed source set with the ccusage tool family,
			// so the unknown-source fixture is a literal that can never be a
			// real source name.
			name:    "unknown source",
			mutate:  func(s *Snapshot) { s.Source = Source("not-a-source") },
			wantErr: "source",
		},
		{
			name:    "bad iso date",
			mutate:  func(s *Snapshot) { s.UsageDate = "2026-02-30" },
			wantErr: "usageDate",
		},
		{
			name:    "non-canonical date",
			mutate:  func(s *Snapshot) { s.UsageDate = "2026-5-9" },
			wantErr: "usageDate",
		},
		{
			name:    "empty timezone",
			mutate:  func(s *Snapshot) { s.Timezone = "  " },
			wantErr: "timezone",
		},
		{
			name:    "timezone with surrounding whitespace",
			mutate:  func(s *Snapshot) { s.Timezone = " Asia/Shanghai" },
			wantErr: "timezone",
		},
		{
			name:    "unknown timezone",
			mutate:  func(s *Snapshot) { s.Timezone = "Mars/Olympus" },
			wantErr: "timezone",
		},
		{
			name:    "unknown correction literal",
			mutate:  func(s *Snapshot) { s.Correction = "codex-other" },
			wantErr: "correction",
		},
		{
			name:    "collectedAt not RFC3339",
			mutate:  func(s *Snapshot) { s.CollectedAt = "2026-05-09 10:00:00" },
			wantErr: "collectedAt",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			snapshot := goldenSnapshotByName(t, "base")
			tc.mutate(&snapshot)
			err := snapshot.Validate()
			if err == nil {
				t.Fatalf("expected error %q, got nil", tc.wantErr)
			}
			if !strings.Contains(err.Error(), tc.wantErr) {
				t.Errorf("error %q does not mention %q", err, tc.wantErr)
			}
		})
	}
}

func TestValidateAcceptsGoldenBase(t *testing.T) {
	if err := goldenSnapshotByName(t, "base").Validate(); err != nil {
		t.Fatalf("base snapshot must validate: %v", err)
	}
	if err := goldenSnapshotByName(t, "extreme-tokens").Validate(); err != nil {
		t.Fatalf("max tokens must validate: %v", err)
	}
}

// Mirrors usage-core isValidIsoDate: canonical YYYY-MM-DD and a real calendar
// date (2026-02-30 is rejected even though the shape matches).
func TestIsValidIsoDate(t *testing.T) {
	valid := []string{"2023-01-01", "2026-12-31", "2024-02-29"}
	invalid := []string{"2026-02-30", "2026-5-9", "26-05-09", "2026-13-01", "2026-05-09T00:00:00Z", ""}
	for _, value := range valid {
		if !IsValidIsoDate(value) {
			t.Errorf("%q should be valid", value)
		}
	}
	for _, value := range invalid {
		if IsValidIsoDate(value) {
			t.Errorf("%q should be invalid", value)
		}
	}
}

func TestIsValidTimezone(t *testing.T) {
	valid := []string{"Asia/Shanghai", "UTC", "Etc/GMT+5", "America/New_York"}
	// `posixrules` is a real tzdata file that Go's loader resolves; Intl — and
	// therefore the server's validation — has no such zone. Accepting it collects
	// fine and then fails every upload, so it is rejected here like `local`.
	invalid := []string{"Mars/Olympus", " Asia/Shanghai", "", "Asia/Shanghai ", "posixrules", "Local", "factory"}
	for _, value := range valid {
		if !IsValidTimezone(value) {
			t.Errorf("%q should be valid", value)
		}
	}
	for _, value := range invalid {
		if IsValidTimezone(value) {
			t.Errorf("%q should be invalid", value)
		}
	}
}

// tzdata must be embedded: Windows and slim containers have no system zone
// database, and the collector validates arbitrary user timezones.
func TestTzdataEmbedded(t *testing.T) {
	if _, err := time.LoadLocation("America/New_York"); err != nil {
		t.Fatalf("embedded tzdata missing: %v", err)
	}
}

// formatJSONFloat must reproduce JavaScript's Number#toString across the
// notation switch points; every expectation here was printed by Node.
func TestFormatJSONFloatMatchesJavaScript(t *testing.T) {
	cases := []struct {
		value float64
		want  string
	}{
		{0, "0"},
		{0.01, "0.01"},
		{0.30000000000000004, "0.30000000000000004"},
		{123.456, "123.456"},
		{1e-6, "0.000001"},
		{0.00000123456, "0.00000123456"},
		{5e-7, "5e-7"},
		{1e-7, "1e-7"},
		{1e21, "1e+21"},
		{1e20, "100000000000000000000"},
		{999999999, "999999999"},
	}
	// Runtime arithmetic so the constant folder cannot round for us.
	for _, tc := range cases {
		one := tc.value
		if got := FormatJSONFloat(one); got != tc.want {
			t.Errorf("FormatJSONFloat(%v) = %q, want %q", tc.value, got, tc.want)
		}
	}
}

// IsValidCollectedAt mirrors Zod datetime() exactly; every expectation here
// was probed against the real schema.
func TestIsValidCollectedAtMatchesZod(t *testing.T) {
	accepted := []string{
		"2026-05-09T10:00:00Z", "2026-05-09T10:00:00.000Z", "2026-05-09T10:00:00.000000Z",
		"2026-05-09T10:00:00.1Z",
	}
	rejected := []string{
		"2026-05-09T10:00:00+08:00", "2026-05-09T10:00:00-05:00", "2026-05-09T10:00:00",
		"2026-05-09 10:00:00Z", "2026-05-09T24:00:00Z", "2026-05-09T10:60:00Z",
		"2026-02-30T10:00:00Z", "2026-05-09T10:00:60Z", "2026-05-09T10:00:00.Z",
		"2026-05-09T10:00:00,000Z", "2026-05-09t10:00:00Z", "2026-05-09T10:00:00.000z",
	}
	for _, value := range accepted {
		if !IsValidCollectedAt(value) {
			t.Errorf("%q should be accepted", value)
		}
	}
	for _, value := range rejected {
		if IsValidCollectedAt(value) {
			t.Errorf("%q should be rejected", value)
		}
	}
}

func TestRejectsEmptyCorrectionLiteral(t *testing.T) {
	snapshot := goldenSnapshotByName(t, "base")
	snapshot.Correction = ""
	if err := snapshot.Validate(); err != nil {
		t.Fatalf("empty correction must behave as absent: %v", err)
	}
	// An explicitly empty JSON string, however, is what Zod rejects; the
	// round-trip through the hash payload omits it, matching JSON.stringify.
	if strings.Contains(snapshot.HashPayload(), "correction") {
		t.Error("empty correction must be omitted from the payload")
	}
}

// Local and Factory resolve in Go's zone loader but are rejected by Intl;
// the TS side would refuse them, so this side must too.
func TestTimezoneRejectsLocalAndFactory(t *testing.T) {
	for _, value := range []string{"Local", "Factory", "local", "factory"} {
		if IsValidTimezone(value) {
			t.Errorf("%q must be rejected like Intl rejects it", value)
		}
	}
}

// Length bounds count UTF-16 code units like Zod's .max(), not bytes: a
// CJK-heavy model name within the limit must pass.
func TestLengthBoundsCountUTF16Units(t *testing.T) {
	snapshot := goldenSnapshotByName(t, "base")
	snapshot.Model = strings.Repeat("模", MaxUsageModelNameLength)
	if err := snapshot.Validate(); err != nil {
		t.Fatalf("%d CJK chars = %d UTF-16 units, must fit: %v",
			MaxUsageModelNameLength, MaxUsageModelNameLength, err)
	}
	snapshot.Model = strings.Repeat("模", MaxUsageModelNameLength+1)
	if err := snapshot.Validate(); err == nil {
		t.Fatal("one unit over the limit must be rejected")
	}
}

// Intl — and therefore usage-core and every TS provider that formats a date
// with it — accepts offset time zone identifiers (±HH:MM, ±HHMM, hours
// 00-23, minutes 00-59). LoadLocation has no such names, so the TS client
// collects under "+08:00" while this one refused the run outright.
// The cache must key on the exact input. LoadLocation is case-sensitive on a
// case-sensitive filesystem while Intl is not, so a lowercase alias that fails
// to load must not inherit a canonical-case hit: the result would otherwise
// depend on which spelling happened to be validated first.
func TestIsValidTimezoneCacheDoesNotLeakAcrossCaseVariants(t *testing.T) {
	if !IsValidTimezone("Asia/Shanghai") {
		t.Fatal("Asia/Shanghai should be valid")
	}
	timezoneMu.RLock()
	_, leaked := timezoneValid["asia/shanghai"]
	timezoneMu.RUnlock()
	if leaked {
		t.Fatal("cache entry keyed by a case variant: each spelling must be validated on its own")
	}
}

func TestIsValidTimezoneAcceptsIntlOffsetZones(t *testing.T) {
	valid := []string{
		"+08:00", "-05:30", "+0800", "-0530", "+00:00", "-00:00", "+23:59", "-23:59",
		// Intl also takes a bare two-digit hour and resolves it to :00.
		"+08", "-08", "+23", "-00",
	}
	invalid := []string{"+24:00", "+24", "+08:60", "+8:00", "+8", "+08:0", "+080", "08:00", "++08:00"}
	for _, value := range valid {
		if !IsValidTimezone(value) {
			t.Errorf("%q should be valid: Intl accepts offset time zones", value)
		}
	}
	for _, value := range invalid {
		if IsValidTimezone(value) {
			t.Errorf("%q should be invalid", value)
		}
	}
}

func TestLoadLocationResolvesOffsetZones(t *testing.T) {
	for name, want := range map[string]int{"+08:00": 8 * 3600, "-05:30": -(5*3600 + 1800), "+0800": 8 * 3600} {
		location, err := LoadLocation(name)
		if err != nil {
			t.Errorf("LoadLocation(%q): %v", name, err)
			continue
		}
		if _, offset := time.Date(2026, 10, 21, 0, 0, 0, 0, location).Zone(); offset != want {
			t.Errorf("LoadLocation(%q) offset = %d, want %d", name, offset, want)
		}
	}
	location, err := LoadLocation("Asia/Shanghai")
	if err != nil || location.String() != "Asia/Shanghai" {
		t.Errorf("LoadLocation(Asia/Shanghai) = %v, %v", location, err)
	}
}

// usageCoreSources is the `usageSources` array from
// packages/usage-core/src/schema.ts, in declaration order. It is copied rather
// than generated so a change on either side has to be made deliberately; the
// parity test below is what fails when the two drift.
var usageCoreSources = []string{
	"claude-code",
	"codex",
	"antigravity-cli",
	"antigravity",
	"antigravity-ide",
	"opencode",
	"pi",
	"grok-build",
	"deepseek-harness",
	"amp",
	"droid",
	"codebuff",
	"hermes",
	"goose",
	"kilo",
	"copilot",
	"gemini-cli",
	"kimi",
	"qwen",
	"openclaw",
	"zcode",
}

// The source list is a wire contract: usage-core's `usageSources` is what the
// server accepts and what the TypeScript collector uploads. A source present
// on one side and missing on the other does not fail loudly — the Go client
// simply never collects it, so an `--source all` run silently under-reports.
// The goldens cannot catch that (they cover the hash payload for one source),
// so the parity is asserted here against the list usage-core exports.
func TestUsageSourcesMatchUsageCore(t *testing.T) {
	goSources := AllSources()
	if len(goSources) != len(usageCoreSources) {
		t.Fatalf("Go has %d sources, usage-core has %d: %v vs %v",
			len(goSources), len(usageCoreSources), goSources, usageCoreSources)
	}
	for index, want := range usageCoreSources {
		if string(goSources[index]) != want {
			t.Errorf("source %d = %q, want %q (order is part of the contract)", index, goSources[index], want)
		}
	}
	for _, source := range usageCoreSources {
		if !IsValidSource(source) {
			t.Errorf("IsValidSource(%q) = false", source)
		}
	}
}
